import {scenarios,defaultScenario} from './fixtures.js';
import {compare,plain,tokens} from './compare.js';
import {navigationLabel,verification,verificationCategories,linkChangeName} from './presentation.js';
import {readingMemory} from './reading.js';
const $=s=>document.querySelector(s);
const el=(tag,cls,txt)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(txt!==undefined)n.textContent=txt;return n;};
let current=defaultScenario,reverse=false,mode='flow',expanded=false,showFormat=true,result,visible=[],active=-1;
const expandedTables=new Set();
const memory=readingMemory(document.querySelector('#document'));
$('.review-toolbar').append($('#swap'));
new ResizeObserver(()=>document.documentElement.style.setProperty('--reading-top',($('.review-toolbar').offsetHeight+24)+'px')).observe($('.review-toolbar'));
let pendingReading=null,renderGeneration=0,hiddenPrevious=null;
function refresh(change){pendingReading=memory.capture();change();render();}
function focusedRows(rows){const keep=new Set([0]);rows.forEach((r,i)=>{if(r.status!=='same')for(let j=Math.max(0,i-1);j<=Math.min(rows.length-1,i+1);j++)keep.add(j);});const out=[];let hidden=0;for(let i=0;i<rows.length;i++){if(!keep.has(i)){hidden++;continue;}if(hidden){out.push({gap:hidden});hidden=0;}out.push(rows[i]);}if(hidden)out.push({gap:hidden});return out;}
const names={text:'文字變更',link:'連結變更',table:'表格變更',format:'格式變更',coarse:'前後內容需核對',unverified:'內容尚未驗證',added:'新增區塊',removed:'刪除區塊',same:'未變內容'};
function warning(message){const n=el('div','notice');n.append(el('span','notice-icon','!'),el('p','',message));return n;}
function preserveFormat(n,f=0){for(const [bit,tag] of [[1,'strong'],[2,'em'],[4,'s'],[8,'u'],[16,'code'],[32,'sub'],[64,'sup']])if(f&bit){const wrapper=el(tag);wrapper.append(...n.childNodes);n.append(wrapper);}return n;}
function diff(a,b,format=0){const n=el('p','diff-line');for(const part of tokens(a,b)){const span=el(part.type==='removed'?'del':part.type==='added'?'ins':'span',part.type==='same'?'':part.type==='removed'?'diff-del':'diff-add',part.text);if(part.type!=='same'){const label=el('span','sr-only',part.type==='removed'?'刪除：':'新增：');span.prepend(label);}n.append(span);}return preserveFormat(n,format);}
function safeUrl(value){try{const u=new URL(value,location.href);return ['https:','http:'].includes(u.protocol)?u.href:null;}catch{return null;}}
function renderNode(node){
 if(!node)return el('p','changed-empty','此版本沒有這個區塊');
 const children=()=> (node.children||[]).map(renderNode);
 switch(node.type){
 case 'root':{const n=el('div');n.append(...children());return n;}
 case 'code-highlight':
 case 'text':{let n=el('span','',node.text);const f=node.format||0;for(const [bit,tag] of [[1,'strong'],[2,'em'],[4,'s'],[8,'u'],[16,'code'],[32,'sub'],[64,'sup']])if(f&bit){const x=el(tag);x.append(n);n=x;}if(f&128)n.style.textTransform='lowercase';if(f&256)n.style.textTransform='uppercase';return n;}
 case 'linebreak':return el('br');
 case 'paragraph':{const n=el('p');n.append(...children());return n;}
 case 'heading':{const n=el(['h1','h2','h3','h4','h5','h6'].includes(node.tag)?node.tag:'h2','context-heading');n.append(...children());return n;}
 case 'link':{const url=safeUrl(node.url);const n=el(url?'a':'span');if(url){n.href=url;n.target='_blank';n.rel='noopener noreferrer';}n.append(...children());return n;}
 case 'list':{const n=el(node.listType==='number'?'ol':'ul');if(node.listType==='number')n.start=node.start||1;n.append(...children());return n;}
 case 'listitem':{const n=el('li');if(node.value)n.value=node.value;n.append(...children());return n;}
 case 'code':{const n=el('div');n.append(el('span','raw-note',node.language||'程式碼'),el('pre','source-box',plain(node)));return n;}
 case 'quote':{const n=el('blockquote','node-quote');n.append(...children());return n;}
 case 'collapse':{const n=el('details','node-collapse');n.open=node.collapsed===false;n.append(el('summary','',node.title||'收合內容'));const inner=el('div','collapse-content');inner.append(el('p','raw-note',node.collapsed===false?'此版本保存時為展開狀態。':'此版本保存時為收合狀態。'),...children());n.append(inner);return n;}
 case 'table':{const outer=el('div','table-scroll');outer.tabIndex=0;outer.setAttribute('aria-label','完整表格，可左右捲動');const n=el('table');const body=el('tbody');body.append(...children());n.append(body);outer.append(n);return outer;}
 case 'tablerow':{const n=el('tr');n.append(...children());return n;}
 case 'tablecell':{const n=el(node.headerState?'th':'td');if(node.headerState===1)n.scope='col';if(node.headerState===2)n.scope='row';n.colSpan=Math.min(100,Math.max(1,Number(node.colSpan)||1));n.rowSpan=Math.min(100,Math.max(1,Number(node.rowSpan)||1));n.append(...children());return n;}
 case 'image':{const n=el('figure');if(['assets/screen-before.svg','assets/screen-after.svg'].includes(node.src)){const img=el('img','media-preview');img.src=node.src;img.alt=node.alt||'操作圖示意';img.width=640;img.height=320;n.append(img);}else n.append(placeholder('無法確認歷史圖片','保留來源資訊，未以目前圖片代替舊版。'));n.append(el('figcaption','',node.caption||node.alt||'未提供圖片描述'),source('圖片來源',node.src));if(node.alt)n.append(source('替代文字',node.alt));if(node.poster)n.append(source('封面來源',node.poster));if(node.assetVersion)n.append(source('資產版本',node.assetVersion));return n;}
 case 'video':{const n=el('div');n.append(placeholder(node.title||'教學影片','此合成案例沒有可播放的歷史影片，無法驗證影片內容。'),source('影片來源',node.src));if(node.alt)n.append(source('替代文字',node.alt));if(node.poster)n.append(source('封面來源',node.poster));if(node.assetVersion)n.append(source('資產版本',node.assetVersion));return n;}
 case 'mermaid':{const n=el('div');n.append(placeholder('流程預覽尚未驗證','請核對下方流程來源；不根據布局猜測邏輯差異。'),el('pre','source-box',node.source||''));return n;}
 default:{const n=el('div');n.append(placeholder('此內容尚未支援',`區塊類型：${node.type}。請由熟悉這類內容的人確認。`),payload(node));return n;}
 }
}
function placeholder(title,msg){const n=el('div','placeholder');n.append(el('strong','',title),el('p','',msg));return n;}
function source(label,value){const n=el('div','url-note');n.append(el('span','',label),el('code','',typeof value==='string'?value:'未提供'));return n;}
function payload(node){const n=el('details','payload');n.append(el('summary','','查看保存資料'),el('pre','source-box',JSON.stringify(node,null,2)));return n;}
function urls(node){const out=[];function visit(n){if(!n)return;if(n.type==='link')out.push(n.url);for(const child of n.children||[])visit(child);}visit(node);return out;}
function pair(record){const grid=el('div','side-grid');for(const [key,label,side] of [['a','基準 A · 原內容','old'],['b','目標 B · 新內容','new']]){const cell=el('div',`side ${side}`);cell.dataset.snapshot=key==='a'?(reverse?'second':'first'):(reverse?'first':'second');cell.append(el('span',`side-label ${side}-label`,label));const content=el('div','prose');
 if(record.kind==='text'){const line=el('p');for(const part of tokens(plain(record.a),plain(record.b))){if((key==='a'&&part.type==='added')||(key==='b'&&part.type==='removed'))continue;line.append(el('span',part.type==='same'?'':key==='a'?'diff-del':'diff-add',part.text));}content.append(preserveFormat(line,record[key]?.children[0]?.format));}
 else if(record.kind==='table')content.append(alignedTable(record,key));
 else content.append(renderNode(record[key]));
 cell.append(content);if(record.kind==='link')for(const url of urls(record[key]))cell.append(source('連結目的地',url));if(record.kind==='unverified'&&record[key]&&['root','paragraph','heading','text','table','quote','collapse','image','video','mermaid'].includes(record[key].type))cell.append(payload(record[key]));grid.append(cell);}return grid;}
function alignedTable(record,key){const outer=el('div','table-scroll');outer.tabIndex=0;outer.setAttribute('aria-label','依已確認列對齊的表格');const table=el('table',(record.a||record.b).children[0].children.length>6?'wide-table':''),body=el('tbody');for(const row of record.rows){const tr=el('tr');if(row.id)tr.dataset.row=row.id;if(row.gap){const c=el('td','table-gap',row.gap+' 列未變內容已收起');c.colSpan=(record.a||record.b).children[0].children.length;tr.append(c);body.append(tr);continue;}const node=row[key];if(!node){const c=el('td','missing-row','此版本沒有這一列');c.colSpan=(row.a||row.b).children.length;tr.append(c);}else for(const [i,c] of node.children.entries()){const td=el(c.headerState?'th':'td');if(c.headerState===1)td.scope='col';if(c.headerState===2)td.scope='row';const changed=row.cells?row.cells[i].changed:true;if(changed)td.className=key==='a'?'split-old-cell':'split-new-cell';td.textContent=plain(c);tr.append(td);}body.append(tr);}table.append(body);outer.append(table);return outer;}
function tableDiff(record){const outer=el('div','table-scroll');outer.tabIndex=0;outer.setAttribute('aria-label','服務承諾差異表，可左右捲動');const table=el('table',(record.a||record.b).children[0].children.length>6?'wide-table':''),body=el('tbody');for(const row of record.rows){if(row.gap){const gap=el('tr'),c=el('td','table-gap',row.gap+' 列未變內容已收起');c.colSpan=(record.a||record.b).children[0].children.length;gap.append(c);body.append(gap);continue;}const tr=el('tr',row.status==='added'?'row-added':row.status==='removed'?'row-removed':'');if(row.id)tr.dataset.row=row.id;if(row.cells){for(const c of row.cells){const cell=el(c.b.headerState?'th':'td',c.changed?'changed-cell':'');if(c.b.headerState===1)cell.scope='col';if(c.b.headerState===2)cell.scope='row';if(c.changed){const old=el('span','cell-old'),next=el('span','cell-new');old.append(el('span','cell-label','− '),document.createTextNode(plain(c.a)));next.append(el('span','cell-label','＋ '),document.createTextNode(plain(c.b)));cell.append(old,next);}else cell.textContent=plain(c.b);tr.append(cell);}}else{for(const [i,c] of (row.b||row.a).children.entries()){const cell=el(c.headerState?'th':'td');if(i===0)cell.append(el('span','row-label',row.status==='added'?'＋ 新增':'− 刪除'));cell.append(document.createTextNode(plain(c)));tr.append(cell);}}body.append(tr);}table.append(body);outer.append(table);return outer;}
function recordCard(r,index){const section=el('article','record');section.id='record-'+r.id;section.dataset.record=r.id;section.tabIndex=-1;const category=verification(r);const header=el('div','record-head');header.append(el('span','record-section',r.section),el('span','record-kind '+(category?'warning':''),category?verificationCategories[category].label:(r.kind==='link'?linkChangeName(r):names[r.kind])),el('span','record-number',String(index+1).padStart(2,'0')));section.append(header,el('h2','change-title',navigationLabel(r)));if(r.reason)section.append(el('p','block-reason '+(['link','format'].includes(r.kind)?'informational':''),r.reason));
 if(category){const c=verificationCategories[category],bar=el('div','verification-detail');bar.append(el('span','',`${r.changed?'保存資料有變動':'保存資料相同；仍有內容待確認'}`));const action=el('button','quiet',c.action);action.onclick=()=>{section.querySelectorAll('.node-collapse,.payload').forEach(n=>n.open=true);const target=section.querySelector(category==='unsupported'?'.payload summary':'.side-grid')||section;target.tabIndex=-1;target.focus({preventScroll:true});target.scrollIntoView({block:'start',behavior:'instant'});};bar.append(action);section.append(bar);}
 if(r.kind==='table'&&r.rows.length>12){const original=r,isOpen=expandedTables.has(r.id);const bar=el('div','table-controls');bar.append(el('span','',isOpen?'完整表格；標頭會保留於捲動區域。':'已聚焦變動列，保留相鄰列與標頭。'));const toggle=el('button','quiet table-toggle',isOpen?'聚焦變動列':`查看完整 ${r.rows.length} 列對照`);toggle.setAttribute('aria-expanded',String(isOpen));toggle.onclick=()=>{isOpen?expandedTables.delete(r.id):expandedTables.add(r.id);const card=recordCard(original,index);section.replaceWith(card);card.querySelector('.table-toggle').focus();syncTableRows();};bar.append(toggle);section.append(bar);if(!isOpen)r={...r,rows:focusedRows(r.rows)};}
 if(mode==='flow'&&r.kind==='text')section.append(diff(plain(r.a),plain(r.b),r.b?.children[0]?.format));
 else if(mode==='flow'&&r.kind==='table')section.append(tableDiff(r));
 else if(mode==='flow'&&['added','removed'].includes(r.kind)){const wrapper=el('div',`prose whole-${r.kind}`);wrapper.append(renderNode(r.b||r.a));section.append(wrapper);}
 else section.append(pair(r));
 return section;}
function contextGroup(group){const details=el('details','unchanged');details.dataset.viewKey='context|'+group.map(r=>r.id).join('|');details.dataset.record='context:'+group[0].id;details.tabIndex=-1;details.open=expanded;details.append(el('summary','',`${group.length} 個未變區塊 · 展開上下文`));const content=el('div','prose');group.forEach(r=>content.append(renderNode(r.b||r.a)));details.append(content);return details;}
function fullDocuments(){const wrap=el('details','unchanged');wrap.append(el('summary','','查看兩份完整文件與原始順序'));const r={a:(reverse?current.b:current.a).editorState.root,b:(reverse?current.a:current.b).editorState.root};wrap.append(pair(r));return wrap;}
function render(){
 const generation=++renderGeneration,saved=pendingReading;pendingReading=null;hiddenPrevious=null;
 const renderStarted=performance.now();
 const a=reverse?current.b:current.a,b=reverse?current.a:current.b;active=-1;visible=[];$('#document').replaceChildren();$('#changes').replaceChildren();$('#status').replaceChildren();
 $('h1').textContent=current.documentTitle||'服務上線與維運規範';$('.subtitle').textContent=current.context||'把注意力留給真正需要審查的內容。';
 $('#task').textContent=current.task;$('#source-note').replaceChildren();if(current.provenance){const sourceLink=el('a','','公開原文與授權');sourceLink.href=current.provenance.source;sourceLink.target='_blank';sourceLink.rel='noopener noreferrer';$('#source-note').append(sourceLink,el('span','',' · '+current.provenance.license));}$('#version-a').textContent=a.revision+' · '+a.label;$('#version-b').textContent=b.revision+' · '+b.label;$('#date-a').textContent=a.savedAt;$('#date-b').textContent=b.savedAt;
 try{result=compare(a,b);}catch(error){const box=el('div','error-state');box.append(el('h2','','這次比較未完成'),el('p','',error.message));const retry=el('button','primary','回到可比較的版本');retry.onclick=()=>{load(defaultScenario.id);$('#document').focus();};box.append(retry);$('#document').append(box);$('#status').append(warning('尚未取得比較結果，不能判定文件是否有變更。'));updateNavigation();$('#position').textContent='尚無可用的比較結果';return;}
 const changed=result.records.filter(r=>r.changed),unverified=result.records.filter(r=>r.needsReview||['coarse','unverified'].includes(r.kind));
 const summary=el('div','status-summary');summary.append(el('strong','',`${changed.length} 個內容變動區塊`),el('span','status-separator','/'),el('span','',`${unverified.length+(result.moved?1:0)} 個區域需要核對`));$('#status').append(summary);
 if(unverified.length){const list=el('div','verification-summary');for(const [key,c] of Object.entries(verificationCategories)){const items=result.records.filter(r=>verification(r)===key);if(!items.length)continue;const button=el('button','verification-category');button.append(el('strong','',`${c.label} · ${items.length}`),el('span','',c.help));button.onclick=()=>jump(visible.findIndex(r=>r.id===items[0].id));list.append(button);}$('#status').append(list);}
 if(result.moved){const n=warning('區塊排列順序已變動。下方依目標版閱讀，不能據此推定完整搬移歷程。');const btn=el('button','','查看兩份原始順序');btn.onclick=()=>{const x=$('#full-order');x.open=true;x.scrollIntoView({block:'start'});x.querySelector('summary').focus();};n.lastChild.append(document.createElement('br'),btn);$('#status').append(n);}
 let context=[];function flush(){if(context.length){$('#document').append(contextGroup(context));context=[];}}
 if(!changed.length&&!unverified.length&&!result.moved){const empty=el('div','empty-state');empty.append(el('span','empty-symbol','✓'),el('h2','','這兩版沒有內容變更'),el('p','','已比較此原型支援的保存內容。你仍可展開完整文件確認。'));$('#document').append(empty);}
 for(const r of result.records){if(r.kind==='same'){context.push(r);continue;}if(r.kind==='format'&&!showFormat){flush();const details=el('details','unchanged');details.id='record-'+r.id;details.dataset.record=r.id;details.tabIndex=-1;details.append(el('summary','',`格式變更已收起 · ${navigationLabel(r)}`),pair(r));$('#document').append(details);continue;}flush();const index=visible.length;visible.push(r);$('#document').append(recordCard(r,index));}flush();
 const full=fullDocuments();full.id='full-order';full.dataset.record='full-order';full.dataset.viewKey='full-order';full.tabIndex=-1;$('#document').append(full);
 $('#changes').append(el('div','nav-label',visible.length?'變更導覽':'文件狀態'));
 visible.forEach((r,i)=>{const btn=el('button','nav-item');btn.dataset.index=i;btn.append(el('span','nav-index',String(i+1).padStart(2,'0')));const label=el('span');label.append(el('strong','',navigationLabel(r)),el('small','',r.section+' · '+(verification(r)?verificationCategories[verification(r)].label:(r.kind==='link'?linkChangeName(r):names[r.kind]))));btn.append(label);btn.onclick=()=>jump(i);$('#changes').append(btn);});
 if(!visible.length)$('#changes').append(el('p','task',result.moved?'排列順序有變動，請查看兩份原始順序。':changed.length?'格式變更目前已收起。':'沒有待查看的變更。'));
 updateNavigation();requestAnimationFrame(()=>{if(generation!==renderGeneration)return;syncTableRows();const id=memory.restore(saved);if(id){active=visible.findIndex(r=>r.id===id);markActive();updateNavigation();if(active<0){const record=result.records.find(r=>r.id===id.replace('context:',''));$('#position').textContent=id==='full-order'?'保留完整文件閱讀位置':id.startsWith('context:')?'保留未變內容閱讀位置':'目前格式變更已收起 · 開啟「顯示格式變更」可回到原項目';const at=id==='full-order'?result.records.length:result.records.indexOf(record);active=visible.filter(r=>result.records.indexOf(r)<at).length-1;hiddenPrevious=active;$('#previous').disabled=active<0;$('#next').disabled=active>=visible.length-1;}}document.querySelector('#document').dataset.renderMs=(performance.now()-renderStarted).toFixed(1);});
}
function syncTableRows(){for(const pair of document.querySelectorAll('.record .side-grid')){const tables=pair.querySelectorAll('table');if(tables.length!==2||!pair.closest('.record').querySelector('.record-kind')?.textContent.includes('表格變更'))continue;const [a,b]=tables;for(const r of [...a.rows,...b.rows])r.style.height='';if(getComputedStyle(pair).gridTemplateColumns.split(' ').length<2)continue;for(let i=0;i<a.rows.length&&i<b.rows.length;i++){const height=Math.max(a.rows[i].getBoundingClientRect().height,b.rows[i].getBoundingClientRect().height);a.rows[i].style.height=b.rows[i].style.height=height+'px';}}}
window.addEventListener('resize',()=>requestAnimationFrame(syncTableRows));
function markActive(){document.querySelectorAll('.nav-item').forEach(n=>{n.classList.toggle('active',Number(n.dataset.index)===active);if(Number(n.dataset.index)===active)n.setAttribute('aria-current','true');else n.removeAttribute('aria-current');});}
function jump(index){if(!visible.length)return;hiddenPrevious=null;active=Math.max(0,Math.min(index,visible.length-1));const card=document.getElementById('record-'+visible[active].id);card.querySelectorAll('.node-collapse').forEach(d=>d.open=true);memory.select(visible[active].id);card.focus({preventScroll:true});card.scrollIntoView({block:'start',behavior:'instant'});markActive();updateNavigation();}
function updateNavigation(){$('#previous').disabled=active<=0;$('#next').disabled=!visible.length||active===visible.length-1;$('#position').textContent=active>=0?`第 ${active+1} / ${visible.length} 項 · ${visible[active].section}`:visible.length?`${visible.length} 項可查看 · 從第一項開始`:'沒有其他變更';}
function load(id){memory.reset();pendingReading=null;expandedTables.clear();current=scenarios.find(s=>s.id===id)||defaultScenario;reverse=false;$('#scenario').value=current.id;history.replaceState(null,'','#'+current.id);render();$('#changes').scrollTop=0;$('#changes').scrollLeft=0;$('.sidebar').scrollTop=0;window.scrollTo(0,0);}
const groups=new Map();scenarios.forEach(s=>{const group=s.group||'審查情境';if(!groups.has(group)){const g=el('optgroup');g.label=group;groups.set(group,g);$('#scenario').append(g);}const option=el('option','',s.title);option.value=s.id;groups.get(group).append(option);});
$('#scenario').onchange=e=>load(e.target.value);
$('#swap').onclick=()=>refresh(()=>{reverse=!reverse;});
$('#flow').onclick=()=>setMode('flow');$('#split').onclick=()=>setMode('split');
function setMode(value){refresh(()=>{mode=value;$('#flow').setAttribute('aria-pressed',String(mode==='flow'));$('#split').setAttribute('aria-pressed',String(mode==='split'));});}
$('#context').onclick=()=>refresh(()=>{expanded=!expanded;$('#context').setAttribute('aria-pressed',String(expanded));$('#context').textContent=expanded?'收合未變內容':'展開未變內容';memory.forgetDetails();});
$('#format-filter').onchange=e=>refresh(()=>{showFormat=e.target.checked;});
$('#previous').onclick=()=>jump(hiddenPrevious??(active-1));$('#next').onclick=()=>jump(active+1);
$('#reset').onclick=()=>{expanded=false;showFormat=true;$('#format-filter').checked=true;$('#context').textContent='展開未變內容';$('#context').setAttribute('aria-pressed','false');setMode('flow');load(defaultScenario.id);window.scrollTo(0,0);};
$('#about').onclick=()=>$('#info').showModal();$('#close-info').onclick=()=>$('#info').close();
$('#download').onclick=()=>{const blob=new Blob([JSON.stringify({scenario:current.title,baseline:reverse?(current.savedB||current.b):(current.savedA||current.a),target:reverse?(current.savedA||current.a):(current.savedB||current.b),scope:current.provenance?'Public article transcription and controlled test edit, not upstream history. Native Lexical JSON plus explicit identity sidecar.':'Synthetic snapshot-demo-v1. Not the production node registry.'},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=`snapshot-${current.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
if(new URLSearchParams(location.search).get('audit')==='grayscale')document.documentElement.dataset.audit='grayscale';
load(location.hash.slice(1));
